begin;
create or replace function "authorization".can_access_intervention(target_school uuid,target_intervention uuid,author_only boolean)returns boolean language sql stable security definer set search_path=''as $$
select coalesce("authorization".improvement_access(target_school)and exists(select 1 from app.interventions i join app.result_revisions r on r.school_id=i.school_id and r.id=i.baseline_result_id join app.assessments a on a.school_id=r.school_id and a.id=r.assessment_id where i.school_id=target_school and i.id=target_intervention and("authorization".can_manage_baseline(target_school,i.baseline_result_id)or(author_only is false and"authorization".current_role(target_school)='student'and i.learner_id="authorization".actor_id()and"authorization".can_learn_course(target_school,a.course_id)))),false)
$$;
create or replace function internal.complete_intervention(target uuid,reflection_text text)returns uuid language plpgsql security definer set search_path=''as $$declare i app.interventions;existing app.intervention_completions;begin select*into i from app.interventions where school_id="authorization".school_id()and id=target for update;if not found or not"authorization".can_access_intervention(i.school_id,i.id,false)or"authorization".current_role(i.school_id)<>'student'or i.learner_id<>"authorization".actor_id()then raise exception 'Completion denied'using errcode='42501';end if;
select*into existing from app.intervention_completions where school_id=i.school_id and intervention_id=i.id;if found then if existing.reflection is distinct from reflection_text then raise exception 'Completion immutable'using errcode='22023';end if;return i.id;end if;
insert into app.intervention_completions(school_id,intervention_id,learner_id,reflection)values(i.school_id,i.id,i.learner_id,reflection_text);update app.interventions set status='COMPLETED',completed_at=coalesce(completed_at,clock_timestamp())where school_id=i.school_id and id=i.id and status='ASSIGNED';return i.id;end$$;
commit;
